import * as React from 'react';

// @interlace/leaderboard v1.0.0 — Interlace design system.
// Docs, props and live preview: https://ds.interlace.tools/c/leaderboard
// What changed since: https://ds.interlace.tools/c/leaderboard#history
// Generated banner — keep it, the upgrade diff reads this version.

/**
 * @interlace/ui — Leaderboard
 *
 * A group's board for a game: rank, name and score, ties sharing a rank,
 * the viewing player's row marked (and kept even when it falls below the
 * top rows), and the whole board held back until enough people have played
 * that no one's score stands alone. Ranking lives in `leaderboard-model.ts`
 * and is exported, so the server that stores scores ranks them the same way.
 *
 * ## Anatomy
 *
 *   Leaderboard                    (div — data-slot="leaderboard", data-state=visible|hidden)
 *     ├─ table                     (data-slot="leaderboard-table", captioned)
 *     │   └─ tr × n                (data-slot="leaderboard-row", data-current, data-rank)
 *     │       ├─ td                (rank: "2" or "=2" when tied)
 *     │       ├─ th scope="row"    (name, with a "You" tag on the viewer's row)
 *     │       └─ td                (score, formatted)
 *     └─ p                         (data-slot="leaderboard-hidden": "Shows once 5 people have played. 3 so far.")
 *
 * A real table, so a screen reader moves by row and column. Rank, name and
 * score are text; the viewer's row is marked by a word and weight, not only
 * a tint.
 *
 * ## Server first
 *
 * No hooks: it renders on the server.
 *
 * ## MIN_VIEWPORT — 320
 *
 * Names truncate before the score column moves.
 *
 * | Rule | Concept                   | Where in this file                         |
 * | ---- | ------------------------- | ------------------------------------------ |
 * | R4   | Extends native el         | `React.ComponentProps<'div'>`              |
 * | R6   | data-slot per part        | leaderboard / -table / -row / -hidden       |
 * | R7   | cn + ...rest              | `cn(…, className)` + `{...props}`          |
 * | R14  | Declares min viewport     | `data-min-viewport` + exported const       |
 * | R19  | Tokens only               | muted, primary, border                     |
 * | R26  | A11y                      | captioned table; row headers; "You" in words |
 */

import { cn } from '@/lib/utils';
import { buildBoard, type LeaderboardEntry, type RankOptions, type RankedEntry } from '@/components/ui/games/leaderboard-model';

export const MIN_VIEWPORT = 320 as const;

interface LeaderboardLabels {
  rank?: string;
  name?: string;
  score?: string;
  /** @default 'You' */
  you?: string;
  /** @default (min, players) => `The board shows once ${min} people have played. ${players} so far.` */
  hidden?: (min: number, players: number) => string;
}

type LeaderboardProps = Omit<React.ComponentProps<'div'>, 'children'> &
  RankOptions & {
    entries: readonly LeaderboardEntry[];
    /** Names the table. */
    caption: React.ReactNode;
    /** Show the caption, or keep it for assistive tech only. @default false */
    showCaption?: boolean;
    /** `Intl.NumberFormat` options for scores. */
    format?: Intl.NumberFormatOptions;
    locale?: string;
    labels?: LeaderboardLabels;
  };

function Row({
  entry,
  current,
  score,
  you,
}: {
  entry: RankedEntry;
  current: boolean;
  score: string;
  you: string;
}) {
  return (
    <tr
      data-slot="leaderboard-row"
      data-rank={entry.rank}
      data-current={current ? '' : undefined}
      className={cn('border-border border-t first:border-t-0', current && 'bg-primary/8')}
    >
      <td className={cn('py-2.5 ps-3 pe-2 tabular-nums', entry.rank <= 3 ? 'font-semibold' : 'text-muted-foreground')}>
        {entry.tied ? `=${entry.rank}` : entry.rank}
      </td>
      <th scope="row" className="max-w-0 py-2.5 pe-2 text-start font-normal">
        <span className="flex min-w-0 items-center gap-2">
          <span className={cn('truncate', current && 'font-semibold')}>{entry.name}</span>
          {current ? (
            <span className="border-primary text-primary shrink-0 rounded-full border px-2 text-xs leading-5 font-semibold">
              {you}
            </span>
          ) : null}
        </span>
      </th>
      <td className={cn('py-2.5 ps-2 pe-3 text-end tabular-nums', current && 'font-semibold')}>{score}</td>
    </tr>
  );
}

function Leaderboard({
  entries,
  caption,
  showCaption = false,
  order,
  minPlayers,
  limit,
  currentId,
  format,
  locale,
  labels,
  className,
  ...props
}: LeaderboardProps) {
  const board = buildBoard(entries, { order, minPlayers, limit, currentId });
  const nf = new Intl.NumberFormat(locale, format);
  const you = labels?.you ?? 'You';

  if (!board.visible) {
    const min = Math.max(1, minPlayers ?? 1);
    return (
      <div
        data-slot="leaderboard"
        data-state="hidden"
        data-min-viewport={String(MIN_VIEWPORT)}
        className={cn('border-border text-muted-foreground rounded-xl border border-dashed p-5 text-sm', className)}
        {...props}
      >
        {showCaption ? <p className="text-foreground mb-1 font-semibold">{caption}</p> : null}
        <p data-slot="leaderboard-hidden">
          {(labels?.hidden ?? ((m: number, p: number) => `The board shows once ${m} people have played. ${p} so far.`))(
            min,
            board.players,
          )}
        </p>
      </div>
    );
  }

  return (
    <div
      data-slot="leaderboard"
      data-state="visible"
      data-min-viewport={String(MIN_VIEWPORT)}
      className={cn('border-border bg-card text-card-foreground overflow-hidden rounded-xl border', className)}
      {...props}
    >
      <table data-slot="leaderboard-table" className="w-full table-fixed border-collapse text-sm">
        <caption
          className={cn(showCaption ? 'border-border border-b px-3 py-2.5 text-start font-semibold' : 'sr-only')}
        >
          {caption}
        </caption>
        <colgroup>
          <col className="w-14" />
          <col />
          <col className="w-24" />
        </colgroup>
        <thead className="sr-only">
          <tr>
            <th scope="col">{labels?.rank ?? 'Rank'}</th>
            <th scope="col">{labels?.name ?? 'Name'}</th>
            <th scope="col">{labels?.score ?? 'Score'}</th>
          </tr>
        </thead>
        <tbody>
          {board.top.map((e) => (
            <Row key={e.id} entry={e} current={e.id === currentId} score={nf.format(e.score)} you={you} />
          ))}
        </tbody>
        {board.current ? (
          <tbody className="border-border border-t border-dashed">
            <Row entry={board.current} current score={nf.format(board.current.score)} you={you} />
          </tbody>
        ) : null}
      </table>
    </div>
  );
}
Leaderboard.displayName = 'Leaderboard';

export { Leaderboard };
export type { LeaderboardProps, LeaderboardLabels };

export interface LeaderboardEntry {
  /** Stable id: a player or a group. */
  id: string;
  /** What the board shows. */
  name: string;
  score: number;
  /** Breaks ties on score: lower first (time taken, say). Equal or missing values share a rank. */
  tiebreak?: number;
}

export interface RankedEntry extends LeaderboardEntry {
  /** 1-based; ties share a rank and the next rank skips (1, 2, 2, 4). */
  rank: number;
  /** True when another entry has the same rank. */
  tied: boolean;
}

export interface RankOptions {
  /** `desc` when a higher score wins. @default 'desc' */
  order?: 'desc' | 'asc';
  /** Below this many entries the board is hidden. @default 1 */
  minPlayers?: number;
  /** Rows to show from the top. @default all */
  limit?: number;
  /** The viewing player's id: their row is kept even outside `limit`. */
  currentId?: string;
}

export interface RankedBoard {
  /** False while fewer than `minPlayers` have played. */
  visible: boolean;
  /** Entries counted. */
  players: number;
  /** The top rows, within `limit`. Empty while hidden. */
  top: RankedEntry[];
  /** The viewing player's row when it falls outside `top`. */
  current?: RankedEntry;
}

/** Rank every entry. */
export function rankEntries(entries: readonly LeaderboardEntry[], order: 'desc' | 'asc' = 'desc'): RankedEntry[] {
  const sign = order === 'desc' ? -1 : 1;
  const sorted = entries
    .slice()
    .sort(
      (a, b) =>
        sign * (a.score - b.score) || (a.tiebreak ?? Infinity) - (b.tiebreak ?? Infinity) || a.name.localeCompare(b.name),
    );
  const same = (a: LeaderboardEntry, b: LeaderboardEntry) => a.score === b.score && (a.tiebreak ?? null) === (b.tiebreak ?? null);
  const ranked: RankedEntry[] = [];
  sorted.forEach((entry, i) => {
    const prev = sorted[i - 1];
    const rank = prev && same(prev, entry) ? (ranked[i - 1] as RankedEntry).rank : i + 1;
    ranked.push({ ...entry, rank, tied: false });
  });
  for (let i = 0; i < ranked.length; i++) {
    const r = ranked[i] as RankedEntry;
    r.tied = ranked[i - 1]?.rank === r.rank || ranked[i + 1]?.rank === r.rank;
  }
  return ranked;
}

/** The board as a page shows it: hidden below the minimum, top rows, and the viewer's own row. */
export function buildBoard(entries: readonly LeaderboardEntry[], options: RankOptions = {}): RankedBoard {
  const { order = 'desc', minPlayers = 1, limit, currentId } = options;
  const players = entries.length;
  if (players < Math.max(1, minPlayers)) return { visible: false, players, top: [] };
  const ranked = rankEntries(entries, order);
  const top = limit === undefined ? ranked : ranked.slice(0, limit);
  const mine = currentId === undefined ? undefined : ranked.find((e) => e.id === currentId);
  const current = mine && !top.includes(mine) ? mine : undefined;
  return { visible: true, players, top, current };
}

/**
 * @interlace/ui — games/leaderboard-model
 *
 * Ranking for a group's board: ties share a rank (1, 2, 2, 4), the board
 * stays hidden until enough people have played, and the player's own row is
 * found even when it falls outside the top rows. Pure, so the server that
 * stores scores ranks them the same way.
 *
 * ## Why a minimum
 *
 * A board of two people tells each of them exactly what the other scored.
 * `minPlayers` keeps a small group's scores private until there are enough
 * of them to stand in a crowd.
 */
